{
  "chapter": 5,
  "sections": [
    {
      "section": "5.1",
      "cuts": [492, 497],
      "paragraphs": [
        {
          "start": 492,
          "end": 496,
          "ending": "重申纯正并非广受好评，并说这层道理要讲得尽量透彻",
          "title": "进入第二层，来看约伯记1章9至10节；今天重点推荐的观念是：纯正并非广受好评，这层道理需要讲得尽量透彻。"
        },
        {
          "start": 497,
          "end": 503,
          "ending": "若一旦动用头脑，许多事情就想不通",
          "title": "回到现实生活中就能意识到，听从神的话所作的决定，在世人看来甚至在自己看来都非常愚拙；人肯听从完全是出于对上帝的信，相信他比自己更了解未来、更掌控万事，基督徒是因信而非因思考行事，一旦动用头脑，许多事就想不通。"
        }
      ],
      "uncertain": [
        {"line": 495, "reason": "495-496 语句零乱（「纯正不应为祸福」），此处与 497 起的现实应用是否应切开拿不准"}
      ]
    },
    {
      "section": "5.2",
      "cuts": [504, 516, 524, 531, 548, 555, 563],
      "paragraphs": [
        {
          "start": 504,
          "end": 515,
          "ending": "落到这个地步还持守纯正，她就不认同他了",
          "title": "约伯记1章9节约伯的妻子对他说「你仍然持守纯正吗？你弃掉神死了吧」；她质疑约伯的理由，正是今天读者称赞约伯的理由——受了两轮伤害竟还持守纯正，落到这个地步还持守纯正，她就不认同他了。"
        },
        {
          "start": 516,
          "end": 523,
          "ending": "读第三章时必须把这些区别读出来",
          "title": "接着从约伯的妻子讲起，第二层要点出两处差异：她对耶和华的信仰与丈夫有何不同，她对约伯的质疑与三个朋友又有何不同；读第三章时必须读出这些区别，这对理解全书非常重要。"
        },
        {
          "start": 524,
          "end": 530,
          "ending": "到第二轮她崩溃了，再也接受不了",
          "title": "约伯的妻子在第一轮灾难中没有留下任何台词，姑且认定她能与丈夫一同承受第一轮的打击；但到第二轮她崩溃了，再也接受不了。"
        },
        {
          "start": 531,
          "end": 547,
          "ending": "太太也受不了灾祸加身，这是夫妻二人的差别",
          "title": "约伯与妻子的差别在于：约伯能接受失去身外之物，也能接受继续失去身内之物、直接从神那里受祸；妻子或许也能接受失去身外之物，赏赐被收走、赤身如出母胎尚且可以认同，却无法接受反过来受祸，所以到第二轮便受不了。"
        },
        {
          "start": 548,
          "end": 554,
          "ending": "赤身归回仍要称颂耶和华，因为人从母胎出来本就一无所有",
          "title": "这样说并没有责怪约伯妻子的意思，就她能承受第一轮而言，今天的人若能如此已非常了不起；用约伯记1章21节约伯的话说，赤身归回仍要称颂耶和华，因为人从母胎出来本就一无所有。"
        },
        {
          "start": 555,
          "end": 562,
          "ending": "这样的纯正很可能令人厌恶，甚至激怒最亲近的人",
          "title": "然而到第二轮撒但再次行动时，约伯已不是出母胎时那种赤身，而是连身体都残缺，一无所有之外又加上一层疾病，却仍持守纯正；这样的纯正很可能令人厌恶，甚至会激怒身边最亲近的人。"
        },
        {
          "start": 563,
          "end": 567,
          "ending": "纯正有时让人厌恶，这是夫妻二人在信仰上的区别",
          "title": "第二层要说明的是：人所想象的与上帝坚贞不渝的美好关系未必换来别人的称赞，落到这般境地仍持守纯正，反而会激怒曾经深爱自己的人，有时纯正令人厌恶，这正是夫妻二人在信仰上的区别。"
        }
      ],
      "uncertain": [
        {"line": 531, "reason": "531-547 共17行，讲夫妻差别是一个完整论证，内部未找到明确切点；535「说的直白一点」属复述标记，故不切"}
      ]
    },
    {
      "section": "5.3",
      "cuts": [568, 578, 587, 599, 610, 624],
      "paragraphs": [
        {
          "start": 568,
          "end": 577,
          "ending": "约伯记的结局反倒是约伯为三个朋友献祭，那是后话",
          "title": "第二点要讲的是约伯的妻子与三个朋友的差异：三个朋友持因果报应观念，一致认定约伯不纯正，认为他家破人亡必是做了坏事，要他认罪好为他祷告；约伯记的结局反倒是约伯为三个朋友献祭，那是后话。"
        },
        {
          "start": 578,
          "end": 586,
          "ending": "三个朋友完全不了解约伯真实的为人",
          "title": "三个朋友远在书亚、提幔等地，与乌斯地有一段距离，只听说约伯破产、又浑身烂疮，并不了解他生活中的作为，结伴来看他、坐在炉灰中哭泣，心里仍认定他犯了罪；约伯一再辩白自己没做错事，双方为此争吵。"
        },
        {
          "start": 587,
          "end": 598,
          "ending": "这份了解反成了她新的责备借口",
          "title": "与三个朋友不同，约伯的妻子朝夕相处，完全知道丈夫是纯正的，正如第9节她所说的「你仍然持守你的纯正吗」；这份了解并不带来同情，反而成了她新的责备借口：敬畏上帝落到这种下场，还持守纯正吗。"
        },
        {
          "start": 599,
          "end": 609,
          "ending": "知与不知，约伯都被骂",
          "title": "三个朋友因不知道约伯纯正而责怪他，妻子却因太知道他的纯正而责怪他，知与不知，约伯都被骂；朋友要他承认干了什么坏事、赶紧悔改，妻子则说既然知道他一生没做过坏事，上帝却这样击打这个家，怎么还在持守纯正。"
        },
        {
          "start": 610,
          "end": 623,
          "ending": "这是约伯所承受的舆论压力",
          "title": "敬畏耶和华的人常遭遇这种处境：怎么做都是错的。朋友不知他清白，就断定他没有持守纯正、弃掉了神；妻子知道真相，却说他都这样了还持守纯正，不如弃掉神去死。理解与不理解他、知道与不知道他真相的人都在指责他。"
        },
        {
          "start": 624,
          "end": 627,
          "ending": "这是约伯常年所承受的属灵霸凌",
          "title": "约伯所受的不只是身体的压力，最令他痛苦的是朋友和妻子；无论知不知道他的为人，他们都在质疑他、打压他，这是约伯常年所承受的属灵霸凌。"
        }
      ],
      "uncertain": [
        {"line": 578, "reason": "578 既有对三个朋友观点的复述，又引出他们在远方、不知约伯作为的新内容，切点拿不准"}
      ]
    },
    {
      "section": "5.4",
      "cuts": [628, 634, 637, 641, 654, 658, 661],
      "paragraphs": [
        {
          "start": 628,
          "end": 633,
          "ending": "这就是约伯的纯正，也就是答案",
          "title": "约伯的纯正所指的就是第10节的话：他对妻子说「你说话像个愚顽的妇人一样，我们从神手里得福，不也受祸吗」，这种由正确认知而来的坚韧就是约伯的纯正。"
        },
        {
          "start": 634,
          "end": 636,
          "ending": "万事互相效力，最终使人得到救恩的益处",
          "title": "约伯之所以能如此，是因为他相信海德堡要理问答所讲的上帝护理既包括得福也包括受祸，而万事互相效力，最终使人得到的是救恩的益处。"
        },
        {
          "start": 637,
          "end": 640,
          "ending": "这是信徒所背诵的金句",
          "title": "约伯后来说，不管那三个人怎么说，他知道他的救赎主活着，末了必站在地上，这正是信徒所背诵的金句。"
        },
        {
          "start": 641,
          "end": 653,
          "ending": "他可以受福也可以受祸，仍不离弃神，这就是他所谓的纯正",
          "title": "约伯在三轮交锋中迸出的信念是：他整卷书从未认为自己病会好，只相信自己死定了；与今天一些人相信宣告病就会好不同，他不认为自己会得医治，却信救赎主活着、末了必站在地上，要在肉身之外得见他。"
        },
        {
          "start": 654,
          "end": 657,
          "ending": "在他身边的人看来，这种纯正令人厌恶",
          "title": "约伯的纯正被当作正面教材，巴不得人去学他；但在约伯身边的人看来，这种纯正却令人厌恶——落到这般地步还持守纯正。"
        },
        {
          "start": 658,
          "end": 660,
          "ending": "约伯不仅知道还坚守这点，仍然不以口犯罪",
          "title": "约伯相信上帝的护理包含得福与受祸；就这一点而言，今天许多基督徒仍然不知道，甚至不愿意承认，而约伯不仅知道，还坚守这点，仍然不以口犯罪。"
        },
        {
          "start": 661,
          "end": 665,
          "ending": "他以纯正的信仰站得稳，但这不代表他没有情绪",
          "title": "约伯在第二轮又赢了：一个抵挡计谋的军装披在他身上，无论撒但想用什么信息差让他弃掉神，他都以纯正的信仰站得稳稳的、不丢掉上帝。"
        }
      ],
      "uncertain": [
        {"line": 641, "reason": "641 语句零乱（「约伯说来说去，说你们胡」），切在 640 与 641 之间还是由 637 起另成一段拿不准"}
      ]
    },
    {
      "section": "5.5",
      "cuts": [666, 671, 682, 692, 702],
      "paragraphs": [
        {
          "start": 666,
          "end": 670,
          "ending": "若坚定纯正，很可能就会遇到这样的处境",
          "title": "第二点共勉是：要把自己所信的建立在上帝自己身上，不要建立在别人的评价上；因为很可能遇到一个处境，身边几乎所有的人对信仰的评价都是错误的。"
        },
        {
          "start": 671,
          "end": 681,
          "ending": "这功夫做起来极其艰难，却极其重要",
          "title": "年轻人讲自我认同、与自己和解，要自己给自己价值，这种说法不可信；应把价值感、对自己的认定和真伪的辨别都放在上帝身上，不建筑在别人的评价上，即迎合神的评价而非人的评价；这功夫说起来容易，做起来却极其艰难，且极其重要。"
        },
        {
          "start": 682,
          "end": 691,
          "ending": "千万不要动摇，动摇取决于对上帝话语的信靠",
          "title": "因为如果真理掌握在少数人手里，而人又碰巧是那少数人，大多数人的评价就一定是错误的；到那时千万不要动摇，动摇与否不取决于自己的固执，而取决于对上帝话语经过正义分解之后的信靠。"
        },
        {
          "start": 692,
          "end": 701,
          "ending": "全人应被上帝的圣言坚固，是心智不移动的坚固",
          "title": "具体方式就是以上帝的话语看待自己，不以人的言语看待自己。约伯仍在持守纯正，他自己认为对，妻子和所有人都认为错；他若服从大多数人的标准，撒但就赢了。全人应当被上帝的圣言坚固，不被人的任何话干扰。"
        },
        {
          "start": 702,
          "end": 710,
          "ending": "这种智慧使人能在言论思潮中摒弃干扰，持守纯正",
          "title": "从约伯的妻子和三个朋友的对话可以清楚读到：约伯在各种谬论的拉扯搅乱中，以神学持守信仰，抵挡三个朋友振振有词的控诉，坚持纯正到底，最终得到耶和华的称赞；这种智慧对任何世代的教会都极其重要。"
        }
      ],
      "uncertain": []
    },
    {
      "section": "5.6",
      "cuts": [711, 717, 721, 728, 734, 743],
      "paragraphs": [
        {
          "start": 711,
          "end": 716,
          "ending": "以耶稣亲口所说的话结束今天的信息",
          "title": "许多人常问「难道全世界都错了，就你们几个基督徒对吗」，这话在基督徒身上确实经常适用，并不是狂妄；因此以耶稣亲口所说马太福音七章13-14节的话来结束今天的信息。"
        },
        {
          "start": 717,
          "end": 720,
          "ending": "引到永生的门窄路小，找到的人也少",
          "title": "耶稣在马太福音七章13-14节亲口说：你们要进窄门，因为引到灭亡的门是宽的、路是大的，进去的人多；引到永生的门是窄的、路是小的，找到的人也少。"
        },
        {
          "start": 721,
          "end": 727,
          "ending": "耶稣却说恰恰这条路能通到永生",
          "title": "门宽人多，意味着走那条路的是大多数人，许多人以为那宽门是对的，耶稣却说它引向灭亡；门窄人少，意味着没几个人找到，很多人因此不服从，耶稣却说恰恰这条路能通到永生。"
        },
        {
          "start": 728,
          "end": 733,
          "ending": "耶稣说真道正是很少人走的道路",
          "title": "因此读圣经不要太快，要读得细一点：引到灭亡的门宽、路大、进去的人多，说明很多人以为这条路是对的，耶稣却说它引向灭亡；门窄、路小、找到的人少，耶稣说真道正是很少人走的道路。"
        },
        {
          "start": 734,
          "end": 742,
          "ending": "耶稣说许多人以为对的那门通向灭亡，少人走的窄路通向永生",
          "title": "若这两拨人聚在一起，言论的主流会由谁主导，是宽门党还是窄门党？所以信不能只用蛮力，得动脑子。宽路上人多，主流一定认为那才是对的，走窄路的只有一小撮人；但耶稣说，许多人以为对的那门通向灭亡，少人走的窄路通向永生。"
        },
        {
          "start": 743,
          "end": 747,
          "ending": "神乐意用人当作愚拙的道理拯救信他的人，这就是上帝的智慧",
          "title": "这就是耶稣原本的话，又回到最开始所读的经文——十字架的道理：世人凭自己的智慧既不认识神，神就乐意用人当作愚拙的道理去拯救那些信他的人，这就是上帝的智慧。"
        }
      ],
      "uncertain": []
    }
  ]
}
